//! Replays the golden corpus generated by
//! `electricity/scripts/generate_schema_corpus.py` -- synthetic documents
//! run through Circuitry's real `jsonschema.Draft7Validator`/`core.
//! document_check.schema_errors` against its own schema files -- against
//! [`electricity_schema::orchestration_errors`] and
//! [`electricity_schema::profile_errors`].
//!
//! Orchestration cases compare the exact, ordered described-error text
//! (issue #528): `orchestration_errors`'s engine path reproduces
//! `core.document_check.schema_errors`'s own wording and order, not just
//! its accept/reject verdict. Profile cases still compare only the
//! accept/reject verdict and each violation's own *location* -- that
//! caller (`cli.profiles`) isn't one of #528's own four, and the
//! `jsonschema`-crate text it still uses there is never required to
//! match Python's word for word (`DESIGN.md` §1, §12).
//!
//! The corpus is checked in (`tests/golden/corpus.json`); CI separately
//! regenerates it (via Circuitry's own validation) and fails the build if
//! it differs (`.github/workflows/electricity-generated.yml`), so this
//! test only needs to trust the committed file.

use electricity_schema::{orchestration_errors, profile_errors, value_from_json};
use serde::Deserialize;
use serde_json::Value;

#[derive(Deserialize)]
struct Case {
    name: String,
    schema: String,
    document: Value,
    valid: bool,
    #[serde(default)]
    locations: Vec<String>,
    #[serde(default)]
    described_errors: Vec<String>,
}

#[test]
fn golden_corpus_matches_circuitry() {
    let text = include_str!("golden/corpus.json");
    let cases: Vec<Case> = serde_json::from_str(text).expect("golden/corpus.json is valid JSON");
    assert!(!cases.is_empty(), "golden corpus must not be empty");

    let mut failures = Vec::new();
    for case in &cases {
        match case.schema.as_str() {
            "orchestration" => {
                let document = value_from_json(&case.document);
                let errors = orchestration_errors(&document, &case.document);
                let is_valid = errors.is_empty();
                if is_valid != case.valid {
                    failures.push(format!(
                        "case {:?}: expected valid={}, got valid={} (errors: {:?})",
                        case.name, case.valid, is_valid, errors
                    ));
                    continue;
                }
                let described: Vec<String> = errors.iter().map(|e| e.describe()).collect();
                if described != case.described_errors {
                    failures.push(format!(
                        "case {:?}: described-error mismatch:\n  expected {:?}\n  got      {:?}",
                        case.name, case.described_errors, described
                    ));
                }
            }
            "profile" => {
                let errors = profile_errors(&case.document);
                let is_valid = errors.is_empty();
                if is_valid != case.valid {
                    failures.push(format!(
                        "case {:?}: expected valid={}, got valid={} (errors: {:?})",
                        case.name, case.valid, is_valid, errors
                    ));
                    continue;
                }
                let mut got_locations: Vec<&str> =
                    errors.iter().map(|e| e.location.as_str()).collect();
                got_locations.sort_unstable();
                let expected_locations: Vec<&str> =
                    case.locations.iter().map(String::as_str).collect();
                if got_locations != expected_locations {
                    failures.push(format!(
                        "case {:?}: location mismatch: expected {:?}, got {:?}",
                        case.name, expected_locations, got_locations
                    ));
                }
                for error in &errors {
                    if error.message.is_empty() {
                        failures.push(format!(
                            "case {:?}: error at {:?} has an empty message",
                            case.name, error.location
                        ));
                    }
                }
            }
            // Replayed against `electricity_compiler::structural_errors`
            // instead, in `electricity-compiler/tests/structural_corpus.rs`
            // -- this crate has no near-miss-unknown-key/`group:`/
            // `interface.inputs`-type-error logic to replay it against.
            "orchestration_structural" => {}
            other => panic!("case {:?}: unknown schema kind {other:?}", case.name),
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
